<?php
/** Bordkhan PHP finance/admin page: gateway settings, receipts, settlements. */
require_once __DIR__ . '/bk_extended.php';
$admin = bk_admin(); $pdo=db(); $notice='';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { if (function_exists('check_csrf')) check_csrf(); }
if (($_POST['finance_action']??'')==='settings') {
    try {
        $fields=['gateway_enabled','gateway_type','gateway_merchant_id','gateway_api_key','gateway_sandbox','gateway_min_charge','gateway_max_charge','z2c_bank_name','z2c_account_name','z2c_card_number'];
        $sets=[];$vals=[];foreach($fields as $f){$sets[]='`'.$f.'`=?';$vals[$f]=trim((string)($_POST[$f]??''));}
        $sql='UPDATE settings SET '.implode(',', $sets).' WHERE id=1';$pdo->prepare($sql)->execute(array_values($vals));$notice='تنظیمات مالی ذخیره شد.';
    } catch (Throwable $e) { $notice='ذخیره انجام نشد؛ ابتدا یک‌بار /php-extended/migrate.php را اجرا کنید.'; }
}
if (($_POST['finance_action']??'')==='receipt') {
    $id=(int)$_POST['tx_id'];$ok=($_POST['status']??'')==='confirmed';$pdo->beginTransaction();
    $q=$pdo->prepare("SELECT * FROM wallet_transactions WHERE id=? AND type='charge' AND method='z2c' AND status='pending' FOR UPDATE");$q->execute([$id]);$tx=$q->fetch();
    if($tx){if($ok){$pdo->prepare('UPDATE users SET balance=balance+? WHERE id=?')->execute([$tx['amount'],$tx['user_id']]);$pdo->prepare("UPDATE wallet_transactions SET status='confirmed',balance_after=(SELECT balance FROM users WHERE id=?) WHERE id=?")->execute([$tx['user_id'],$id]);bk_notify((int)$tx['user_id'],'فیش کارت‌به‌کارت تأیید شد',money($tx['amount']).' تومان به کیف پول اضافه شد.',url('wallet'),'wallet');$notice='فیش تأیید و موجودی اضافه شد.';}else{$pdo->prepare("UPDATE wallet_transactions SET status='rejected' WHERE id=?")->execute([$id]);bk_notify((int)$tx['user_id'],'فیش کارت‌به‌کارت رد شد','فیش واریزی شما رد شد؛ با پشتیبانی تماس بگیرید.',url('wallet'),'wallet');$notice='فیش رد شد.';}$pdo->commit();}else{$pdo->rollBack();$notice='فیش یافت نشد یا قبلاً بررسی شده است.';}
}
if (($_POST['finance_action']??'')==='settlement') {
    $id=(int)$_POST['withdrawal_id'];$status=in_array($_POST['status']??'', ['paid','rejected','reviewing'],true)?$_POST['status']:'reviewing';$q=$pdo->prepare('SELECT * FROM withdrawals WHERE id=? FOR UPDATE');$q->execute([$id]);$w=$q->fetch();
    if($w && $w['status']!==$status){$pdo->beginTransaction();if($status==='rejected' && $w['status']!=='rejected'){$pdo->prepare('UPDATE users SET balance=balance+? WHERE id=?')->execute([$w['amount'],$w['user_id']]);bk_tx((int)$w['user_id'],(int)$w['amount'],'withdrawal_cancel','بازگشت تسویه ردشده');} $pdo->prepare('UPDATE withdrawals SET status=?,admin_note=?,reviewed_at=IF(? IN ("paid","rejected"),NOW(),NULL) WHERE id=?')->execute([$status,bk_clean($_POST['note']??''),$status,$id]);$pdo->commit();$notice='وضعیت تسویه به‌روزرسانی شد.';}else{$notice='تسویه یافت نشد یا قبلاً پردازش شده است.';}
}
$s=$pdo->query('SELECT * FROM settings WHERE id=1')->fetch()?:[];$receipts=$pdo->query("SELECT t.*,u.name user_name,u.phone FROM wallet_transactions t JOIN users u ON u.id=t.user_id WHERE t.type='charge' AND t.method='z2c' AND t.status='pending' ORDER BY t.created_at DESC")->fetchAll();$withdrawals=$pdo->query("SELECT w.*,u.name user_name,u.phone FROM withdrawals w JOIN users u ON u.id=w.user_id WHERE w.status IN ('pending','reviewing') ORDER BY w.created_at DESC")->fetchAll();
header_html('مدیریت مالی');
?><main class="wrap page"><div class="page-title"><h1>مدیریت مالی و درگاه</h1><p><?=h($notice)?></p></div><div class="card auth-card"><h3>تنظیمات درگاه</h3><form method="post"><input type="hidden" name="csrf" value="<?=function_exists('csrf')?csrf():''?>"><input type="hidden" name="finance_action" value="settings"><div class="grid grid-2"><div><label class="field-label">فعال</label><select class="field" name="gateway_enabled"><option value="1" <?=!empty($s['gateway_enabled'])?'selected':''?>>فعال</option><option value="0" <?=empty($s['gateway_enabled'])?'selected':''?>>غیرفعال</option></select></div><div><label class="field-label">درگاه</label><select class="field" name="gateway_type"><?php foreach(['zarinpal','idipay','zibal'] as $g):?><option value="<?=$g?>" <?=($s['gateway_type']??'zarinpal')===$g?'selected':''?>><?=$g?></option><?php endforeach;?></select></div><div><label class="field-label">Merchant ID</label><input class="field" name="gateway_merchant_id" value="<?=h($s['gateway_merchant_id']??'')?>"></div><div><label class="field-label">API Key آیدیپی</label><input class="field" type="password" name="gateway_api_key" value="<?=h($s['gateway_api_key']??'')?>"></div><div><label class="field-label">Sandbox</label><select class="field" name="gateway_sandbox"><option value="1" <?=!empty($s['gateway_sandbox'])?'selected':''?>>بله</option><option value="0" <?=empty($s['gateway_sandbox'])?'selected':''?>>خیر</option></select></div><div><label class="field-label">حداقل / حداکثر شارژ</label><div class="flex gap"><input class="field" type="number" name="gateway_min_charge" value="<?=h($s['gateway_min_charge']??100000)?>"><input class="field" type="number" name="gateway_max_charge" value="<?=h($s['gateway_max_charge']??50000000)?>"></div></div><div><label class="field-label">بانک کارت‌به‌کارت</label><input class="field" name="z2c_bank_name" value="<?=h($s['z2c_bank_name']??'')?>"></div><div><label class="field-label">به نام</label><input class="field" name="z2c_account_name" value="<?=h($s['z2c_account_name']??'')?>"></div><div><label class="field-label">شماره کارت</label><input class="field" dir="ltr" name="z2c_card_number" value="<?=h($s['z2c_card_number']??'')?>"></div></div><button class="btn btn-primary mt">ذخیره تنظیمات</button></form></div><div class="card auth-card mt"><h3>فیش‌های کارت‌به‌کارت در انتظار</h3><?php foreach($receipts as $r):?><div class="aline"><div class="grow"><b><?=h($r['user_name'])?> — <?=money($r['amount'])?> تومان</b><small><?=h($r['bank_name'])?> · <?=h($r['card_number'])?></small><?php if($r['receipt_url']):?><a class="check" target="_blank" href="<?=h($r['receipt_url'])?>">مشاهده فیش</a><?php endif;?></div><form method="post"><input type="hidden" name="csrf" value="<?=function_exists('csrf')?csrf():''?>"><input type="hidden" name="finance_action" value="receipt"><input type="hidden" name="tx_id" value="<?=$r['id']?>"><button class="btn btn-primary btn-sm" name="status" value="confirmed">تأیید</button><button class="btn btn-danger btn-sm" name="status" value="rejected">رد</button></form></div><?php endforeach;?><?php if(!$receipts):?><div class="empty">فیشی در انتظار بررسی نیست.</div><?php endif;?></div><div class="card auth-card mt"><h3>تسویه‌های در انتظار</h3><?php foreach($withdrawals as $w):?><div class="aline"><div class="grow"><b><?=h($w['user_name'])?> — <?=money($w['amount'])?> تومان</b><small dir="ltr">شبا: <?=h($w['shaba'])?> · کارت: <?=h($w['card_number'])?> · کدملی: <?=h($w['national_id'])?></small></div><form method="post"><input type="hidden" name="csrf" value="<?=function_exists('csrf')?csrf():''?>"><input type="hidden" name="finance_action" value="settlement"><input type="hidden" name="withdrawal_id" value="<?=$w['id']?>"><button class="btn btn-primary btn-sm" name="status" value="paid">واریز شد</button><button class="btn btn-danger btn-sm" name="status" value="rejected">رد و برگشت</button></form></div><?php endforeach;?><?php if(!$withdrawals):?><div class="empty">تسویه‌ای در انتظار بررسی نیست.</div><?php endif;?></div></main><?php footer_html();
